inline bool RegionGuardsMatch(uintptr_t base) {
    uintptr_t target{};
    if(!ReadMemory(reinterpret_cast<void*>(base+0xd09998),&target,sizeof(target)) || target!=base+0x4b82f0)return false;
    for(const auto& guard:RegionGuards())
        if(!MatchesInstructions(reinterpret_cast<void*>(base+guard.rva),std::span<const uint8_t>(guard.bytes).first(guard.size)))return false;
    return true;
}
